static void verifyAramToDecomp(JKRAramBlock* block){
 alignas(32) u8 packed[32]={'Y','a','z','0',0,0,0,6,0,0,0,0,0,0,0,0,0xE0,'A','B','C',0x10,2};
 alignas(32) u8 staged[32]{};u8 decoded[8]{};
 assert(nativeUploadAram(block->getAddress(),packed,sizeof(packed)));
 assert(nativeDownloadAram(block->getAddress(),staged,sizeof(staged)));
 auto* decoder=JKRDecomp::create(7);assert(decoder);
 assert(JKRDecomp::orderSync(staged,decoded,22,0));
 assert(std::memcmp(decoded,"ABCABC",6)==0 && decoded[6]==0);
 decoder->~JKRDecomp();JKRHeap::free(decoder,nullptr);JKRDecomp::sDecompObject=nullptr;
}
int main(){std::setvbuf(stdout,nullptr,_IONBF,0);alignas(32) uint8_t parentStorage[262144]{};JKRExpHeap parent(parentStorage,sizeof(parentStorage),nullptr,false);JKRHeap::sRootHeap=&parent;JKRHeap::sSystemHeap=&parent;parent.becomeCurrentHeap();auto initial=parent.getTotalFreeSize();std::array<uint8_t,131072> backing{};for(u32 graph:{65536u,0xffffffffu}){auto memory=std::make_shared<NativeAramMemory>(backing.data(),backing.size());assert(nativeBindAramTransport(memory));{JKRAram manager(8192,graph,16);assert(manager.mStackSize==49152 && manager.mMessageCount==32);assert(manager.mAudioMemoryPtr==0x4000 && manager.mAudioMemorySize==8192);assert(manager.mGraphMemoryPtr==0x6000);assert(manager.mGraphMemorySize==(graph==0xffffffffu?106496u:65536u));assert(manager.mAramMemorySize==(graph==0xffffffffu?0u:40960u));assert(manager.mAramMemoryPtr==(graph==0xffffffffu?0u:0x16000u));auto block=manager.mAramHeap->alloc(64,JKRAramHeap::HEAD);assert(block && block->getAddress()==manager.mGraphMemoryPtr);verifyAramToDecomp(block);alignas(32) std::array<u8,32> compressed{};std::memcpy(compressed.data(),"Yaz0",4);compressed[7]=6;compressed[16]=0xe0;std::memcpy(compressed.data()+17,"ABC",3);compressed[20]=0x10;compressed[21]=2;auto* decoder=JKRDecomp::create(7);assert(decoder);u32 uploadedSize=0;auto* uploadResult=JKRAram::mainRamToAram(compressed.data(),0x1000,0,EXPAND_SWITCH_UNKNOWN1,22,nullptr,-1,&uploadedSize);assert(uploadResult==reinterpret_cast<JKRAramBlock*>(static_cast<intptr_t>(-1)) && uploadedSize==32 && std::memcmp(backing.data()+0x1000,"ABCABC",6)==0);decoder->~JKRDecomp();JKRHeap::free(decoder,nullptr);JKRDecomp::sDecompObject=nullptr;std::array<uint8_t,64> input{},output{}; for(unsigned i=0;i<input.size();++i)input[i]=i*7+3; assert(nativeUploadAram(block->getAddress(),input.data(),input.size())); assert(std::equal(input.begin(),input.end(),backing.begin()+block->getAddress())); assert(nativeDownloadAram(block->getAddress(),output.data(),output.size()) && input==output); output.fill(0); assert(!nativeDownloadAram(block->getAddress()+1,output.data(),output.size())); for(auto byte:output)assert(byte==0); assert(!nativeUploadAram(block->getAddress()+1,input.data(),input.size())); assert(!nativeUploadAram(block->getAddress(),input.data(),63));  u32 copied=0;assert(JKRAram::aramToMainRam(block->getAddress(),output.data(),64,EXPAND_SWITCH_UNKNOWN0,0,nullptr,-1,&copied)==output.data() && copied==64 && input==output);
 for(bool yay:{false,true}){std::array<uint8_t,32> packed{};std::memcpy(packed.data(),yay?"Yay0":"Yaz0",4);packed[7]=4;if(yay){packed[11]=20;packed[15]=20;packed[16]=0xff;std::memcpy(packed.data()+20,"ABCD",4);}else{packed[16]=0xf0;std::memcpy(packed.data()+17,"ABCD",4);}assert(nativeUploadAram(block->getAddress(),packed.data(),32)); output.fill(0);assert(JKRAram::aramToMainRam(block->getAddress(),output.data(),32,EXPAND_SWITCH_UNKNOWN1,2,nullptr,-1,&copied)==output.data() && copied==2 && output[0]=='A' && output[1]=='B' && output[2]==0);auto expanded=JKRAram::aramToMainRam(block->getAddress(),nullptr,32,EXPAND_SWITCH_UNKNOWN1,0,&parent,-1,&copied);assert(expanded && copied==4 && !std::memcmp(expanded,"ABCD",4));JKRHeap::free(expanded,&parent);}
 assert(nativeUploadAram(block->getAddress(),input.data(),64)); auto src=memory->bindCpu(input.data(),input.size()),dst=memory->bindCpu(output.data(),output.size()); JKRAMCommand command; command.mTransferDirection=0; command.mSrc=src; command.mDst=block->getAddress(); command.mDataLength=64; auto enqueue=[&]{void* storage=JKRHeap::alloc(sizeof(JKRAramCommand),32,&parent); assert(storage); auto message=new(storage) JKRAramCommand; message->setting(1,&command); assert(OSSendMessage(&JKRAram::sMessageQueue,message,OS_MESSAGE_BLOCK));}; enqueue(); OSResumeThread(manager.mThread); OSMessage done=nullptr; assert(OSReceiveMessage(&command.mMessageQueue,&done,OS_MESSAGE_BLOCK) && done==&command); assert(std::equal(input.begin(),input.end(),backing.begin()+block->getAddress())); command.mTransferDirection=1; command.mSrc=block->getAddress(); command.mDst=dst; enqueue(); assert(OSReceiveMessage(&command.mMessageQueue,&done,OS_MESSAGE_BLOCK) && done==&command && input==output); output.fill(0); assert(JKRAramPiece::orderSync(0,src,block->getAddress(),64,block)); assert(JKRAramPiece::orderSync(1,block->getAddress(),dst,64,block)); assert(input==output); auto async=JKRAramPiece::orderAsync(1,block->getAddress(),dst,64,block,nullptr); assert(async && JKRAramPiece::sync(async,0)); delete async; assert(memory->unbindCpu(src) && memory->unbindCpu(dst)); delete block;}nativeReleaseAramTransport();assert(parent.check() && parent.getTotalFreeSize()==initial);assert(JKRThread::sThreadList.getNumLinks()==0 && JKRAramHeap::sAramList.getNumLinks()==0);}std::puts("PASS ARAM partitions, transfers, queued Yaz0 decompression, allocator and worker teardown");}





